(* [comment removed for export] *)
Definition ds_spec2 (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (s n valp sp r : Z) (bs : list Z),
    PMSP.model_ok model -> K [] ->
    WDL.entry_scr AD L R M sp r VD.DS_SCR ->
    getr R 10%bv = Z_to_bv 64 s -> getr R 11%bv = Z_to_bv 64 n -> getr R 12%bv = Z_to_bv 64 valp ->
    Z.of_nat (length bs) = n -> 1 <= n <= WDL.SNP_MAX -> (WDL.gnum bs = true \/ WDL.gspecial bs) -> L5.bytes_at RSEGS M s (bs ++ [0]) ->
    sp <= s -> s + n + 1 <= hl_sptop L -> sp <= valp -> valp + 8 <= hl_sptop L -> L5.defined M valp 8 -> (valp + 8 <= s \/ s + n + 1 <= valp) ->
    PMST.base_ok RSEGS AD M ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (ec : Z),
        regs_preserved R R' -> getr R' 11%bv = Z_to_bv 64 ec -> (ec = 0 \/ ec = 34) ->
        L5.bytes_at RSEGS M' s (bs ++ [0]) ->
        WDL.mframe L sp VD.DS_SCR [(valp, 8)] M M' -> PMST.base_ok RSEGS AD M' ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model) K) ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R pc M model) K.

