(* [comment removed for export] *)
Lemma step_sw : forall (fx : FPState) segs regs pc mem rom w (rs1 rs2 : bv 5) (imm : bv 12),
  fetch_word segs pc = Some w -> is_ecall w = false ->
  decode_any w = Some (Store SZ4 rs1 rs2 imm, 4%Z) ->
  RiscvSemantics.store_ok segs mem (v_addi (getr regs rs1) (bv_signed imm)) 4%nat = true ->
  RiscvSemantics.step segs (@mkst fx regs pc mem rom) =
  MachineOk (@mkst fx regs (v_addi pc 4) (wbytes mem (v_addi (getr regs rs1) (bv_signed imm)) (Z_to_le_bytes 4 (bv_unsigned (low32 (getr regs rs2))))) rom).
