Definition KEPT : list nat := [3; 4; 20; 21; 22; 23; 24; 25; 26; 27]%nat.
Definition RC (R' : bvmap 5 word) : Prop :=
  getr R' (reg 2) = Z_to_bv 64 (sp - 160) /\ getr R' (reg 8) = Z_to_bv 64 so /\ (forall j, In j KEPT -> getr R' (reg j) = getr R (reg j)).
