Definition VM (d n ec n2 : Z) : nat -> Z := fun j =>
  match j with 2%nat => sp | 33%nat => os | 34%nat => so | 35%nat => r | 36%nat => sv 8 | 37%nat => sv 9 | 38%nat => sv 18 | 39%nat => sv 19
  | 50%nat => dp | 51%nat => d | 52%nat => n | 53%nat => ec | 54%nat => n2 | _ => 0 end.
